userDefinedLinkHintCss:
/* --- Base style --- */
div > .vimiumHintMarker {
  border-radius: 6px;
  padding: 2px 6px;
  font-family: "Segoe UI", "Roboto", sans-serif;
  transition: transform 0.1s ease, background 0.2s ease;
  box-shadow: 0 1px 4px rgba(0,0,0,0.25);
}

div > .vimiumHintMarker:hover {
  transform: scale(1.05);
}

div > .vimiumHintMarker span {
  font-weight: 600;
  font-size: 13px;
  letter-spacing: 0.3px;
}

/* --- Highlight typed characters --- */
div > .vimiumHintMarker > .matchingCharacter {
  font-weight: 700;
  border-radius: 3px;
  padding: 0 2px;
}

/* --- Light Mode --- */
@media (prefers-color-scheme: light) {
  div > .vimiumHintMarker {
    background: linear-gradient(135deg, #fdfbda, #fcd34d);
    border: 1px solid #eab308;
  }

  div > .vimiumHintMarker span {
    color: #1f2937; /* slate-800 */
  }

  div > .vimiumHintMarker > .matchingCharacter {
    background: #fca5a5; /* red-300 */
    color: #991b1b;     /* red-800 */
  }
}

/* --- Dark Mode --- */
@media (prefers-color-scheme: dark) {
  div > .vimiumHintMarker {
    background: linear-gradient(135deg, #3f3f46, #52525b);
    border: 1px solid #a1a1aa; /* zinc-400 */
  }

  div > .vimiumHintMarker span {
    color: #f9fafb; /* near white */
  }

  div > .vimiumHintMarker > .matchingCharacter {
    background: #ef4444; /* red-500 */
    color: #f9fafb;      /* white */
  }
}
